import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Mars (Hỏa Tinh)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/mars.md","filePath":"astro/planets/mars.md"}'),r={name:"astro/planets/mars.md"};function o(c,n,g,s,l,e){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="mars-hoa-tinh" tabindex="-1">Mars (Hỏa Tinh) <a class="header-anchor" href="#mars-hoa-tinh" aria-label="Permalink to &quot;Mars (Hỏa Tinh)&quot;">​</a></h1><blockquote><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong các trang bạn chụp. <strong>[Bổ sung]</strong> = kiến thức traditional astrology nói chung, mình thêm vào để nối với phần đã học. Phần [Bổ sung] nên đối chiếu lại với các chương sau của sách (đặc biệt các con số).</p></blockquote><hr><h2 id="_1-vi-tri-cua-mars-trong-he-thong" tabindex="-1">1. Vị trí của Mars trong hệ thống <a class="header-anchor" href="#_1-vi-tri-cua-mars-trong-he-thong" aria-label="Permalink to &quot;1. Vị trí của Mars trong hệ thống&quot;">​</a></h2><ul><li>Mars là <strong>lesser malefic</strong> (malefic nhỏ) [bổ sung, nối với bài benefic/malefic]</li><li>Mars là malefic của <strong>phe đêm</strong> (nocturnal): lá số đêm thì Mars in sect, &quot;đỡ khó chịu hơn&quot;; lá số ngày thì Mars out of sect, nặng nề hơn</li><li>Tính chất đối lập với Venus: Venus kết nối và hòa hợp, Mars tách ra và va chạm</li></ul><p><strong>Hiểu đơn giản:</strong> Mars giống một người lính. Có kỷ luật, đúng chỗ, đúng lúc thì bảo vệ được cả nhóm. Bị bỏ mặc hoặc đặt sai chỗ thì gây rắc rối cho chính nhóm đó.</p><hr><h2 id="_2-ban-chat-va-y-nghia-sach" tabindex="-1">2. Bản chất và ý nghĩa [Sách] <a class="header-anchor" href="#_2-ban-chat-va-y-nghia-sach" aria-label="Permalink to &quot;2. Bản chất và ý nghĩa [Sách]&quot;">​</a></h2><ul><li>Sức mạnh <strong>khô, bốc lửa, nóng</strong>, có tính <strong>hủy hoại sinh lực</strong> (cả trong tự nhiên lẫn tính cách con người)</li></ul><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung</th></tr></thead><tbody><tr><td>Bạo lực</td><td>Chiến tranh, giận dữ, giết người, nguy hiểm, liều lĩnh, săn đuổi, đánh nhau, tra tấn, đổ máu</td></tr><tr><td>Quan hệ</td><td>Xa cách, rạn nứt tình bạn, kẻ thù, kiện tụng, trộm cắp, bị lấy mất tài sản</td></tr><tr><td>Lời nói</td><td>Dối trá, trách móc, khai man</td></tr><tr><td>Nghề</td><td>Người đạt mục đích bằng <strong>lửa hoặc sắt</strong></td></tr><tr><td>Tình dục</td><td>Xung lực sinh sản, giao hợp, ngoại tình, hủy hoại phụ nữ, phá thai</td></tr><tr><td>Cơ thể</td><td>Đầu, mông/hậu môn, bộ phận sinh dục, máu, ống dẫn tinh, mật, tuyến thượng thận, bài tiết; gây sốt, viêm, loét, mụn mủ</td></tr><tr><td>Màu / vị</td><td>Đỏ / chua gắt</td></tr><tr><td>Kim loại</td><td>Sắt</td></tr><tr><td>Ngày</td><td>Thứ Ba</td></tr></tbody></table><h3 id="condition-tot-vs-xau-theo-sach-sach" tabindex="-1">Condition tốt vs xấu theo sách [Sách] <a class="header-anchor" href="#condition-tot-vs-xau-theo-sach-sach" aria-label="Permalink to &quot;Condition tốt vs xấu theo sách [Sách]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tốt</th><th>Xấu</th></tr></thead><tbody><tr><td>Táo bạo, dũng cảm, quả cảm, bất khuất, quen với nguy hiểm; chỉ tướng lĩnh, chiến binh, thành công trong chiến trận</td><td>Khiến người đó làm điều sai trái, báng bổ, không kiểm soát được, liều lĩnh; có thể gây đau đớn thể xác nghiêm trọng</td></tr></tbody></table><h3 id="than-thoai-va-ten-goi-sach" tabindex="-1">Thần thoại và tên gọi [Sách] <a class="header-anchor" href="#than-thoai-va-ten-goi-sach" aria-label="Permalink to &quot;Thần thoại và tên gọi [Sách]&quot;">​</a></h3><ul><li>Tên thơ ca: <em>Puroeides</em> (= kẻ bốc lửa)</li><li>Nergal (Babylon): thần cõi âm, sốt, dịch bệnh, chiến tranh</li><li>Arēs (Hy Lạp): thần chiến tranh, bạo lực, cơn giận</li><li>Martus/Mars (La Mã): người bảo vệ đế chế bằng sức mạnh quân sự và lòng dũng cảm</li></ul><h3 id="cot-loi-sach" tabindex="-1">Cốt lõi [Sách] <a class="header-anchor" href="#cot-loi-sach" aria-label="Permalink to &quot;Cốt lõi [Sách]&quot;">​</a></h3><ul><li>Bản chất (Valens): <strong>To energize</strong> (tiếp năng lượng), essence: <strong>action and effort</strong> (hành động và nỗ lực)</li><li>Archetype hiện đại: <strong>The Warrior and Competitor</strong></li></ul><p><strong>Cách nhớ:</strong> Mars là &quot;động cơ và lưỡi dao&quot;. Mọi thứ cần lực đẩy, cần cắt, cần quyết liệt đều có dấu Mars. Cùng một năng lượng, đặt đúng chỗ là dũng cảm, đặt sai chỗ là hung hăng.</p><hr><h2 id="_3-essential-dignity-cua-mars-bo-sung" tabindex="-1">3. Essential dignity của Mars [Bổ sung] <a class="header-anchor" href="#_3-essential-dignity-cua-mars-bo-sung" aria-label="Permalink to &quot;3. Essential dignity của Mars [Bổ sung]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loại</th><th>Vị trí</th><th>Ý nghĩa dễ hiểu</th></tr></thead><tbody><tr><td>Domicile</td><td><strong>Aries</strong> và <strong>Scorpio</strong></td><td>Ở nhà mình, hành động đúng sở trường</td></tr><tr><td>Exaltation</td><td><strong>Capricorn</strong> (nổi tiếng là khoảng 28°)</td><td>Được tôn vinh, kỷ luật gắn với sức mạnh</td></tr><tr><td>Triplicity</td><td>Nhóm <strong>nước</strong> (Cancer, Scorpio, Pisces), Mars cai quản <strong>ban đêm</strong> (theo hệ Dorotheus, hệ phổ biến nhất)</td><td>Có chỗ dựa vào ban đêm</td></tr><tr><td>Detriment</td><td><strong>Libra</strong> và <strong>Taurus</strong></td><td>Đối diện nhà mình</td></tr><tr><td>Fall</td><td><strong>Cancer</strong></td><td>Đối diện nơi được tôn vinh</td></tr></tbody></table><p><strong>Nhắc lại từ Figure 3:</strong> khi dùng traditional astrology, <strong>Scorpio do Mars cai quản</strong> (không phải Pluto). Ví dụ Maria von Trapp ở bài trước: house 2 là Scorpio, nên Mars là ruler của house 2.</p><p><strong>Ví dụ cụ thể:</strong></p><ul><li>Mars ở Capricorn: năng lượng có kỷ luật, làm việc bền bỉ, có mục tiêu. Hợp với người lính, thợ cả, vận động viên chịu tập luyện dài hạn</li><li>Mars ở Cancer (fall): muốn hành động nhưng môi trường cảm xúc cản trở, dễ hành động thụ động-gây hấn hoặc bộc phát vì cảm xúc</li><li>Mars ở Libra (detriment): Libra là sign của hòa hợp, trong khi Mars thích đối đầu, dễ phân vân giữa &quot;đánh&quot; và &quot;nhường&quot;</li></ul><hr><h2 id="_4-sect-joy-phase-cua-mars-bo-sung" tabindex="-1">4. Sect, Joy, Phase của Mars [Bổ sung] <a class="header-anchor" href="#_4-sect-joy-phase-cua-mars-bo-sung" aria-label="Permalink to &quot;4. Sect, Joy, Phase của Mars [Bổ sung]&quot;">​</a></h2><ul><li><strong>Sect:</strong> malefic của phe đêm <ul><li>Lá số đêm: Mars <strong>in sect</strong>, ít gây hại hơn</li><li>Lá số ngày: Mars <strong>out of sect</strong>, khó lường hơn</li></ul></li><li><strong>Joy:</strong> <strong>House 6</strong> (bệnh tật, lao dịch, chấn thương). Khớp với ý &quot;sốt, viêm, chấn thương&quot; của sách</li><li><strong>Tốc độ:</strong> Mars đi một vòng zodiac khoảng 2 năm, ở mỗi sign vài tuần. Retrograde khoảng một lần mỗi 2 năm và kéo dài vài tháng: hành động bị trì hoãn, năng lượng bị dồn nén</li><li><strong>Solar phase:</strong> combust (quá gần Sun) làm Mars mất lực, giống người lính bị che mắt. Oriental (mọc trước Sun) thường mạnh và chủ động hơn; occidental (mọc sau Sun) thường bị coi là yếu hơn. Hãy đối chiếu với chương solar phase</li></ul><hr><h2 id="_5-mars-tot-vs-xau-đoc-nhu-the-nao" tabindex="-1">5. Mars tốt vs xấu: đọc như thế nào <a class="header-anchor" href="#_5-mars-tot-vs-xau-đoc-nhu-the-nao" aria-label="Permalink to &quot;5. Mars tốt vs xấu: đọc như thế nào&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition tốt</th><th>Condition xấu</th></tr></thead><tbody><tr><td>Ở Aries/Scorpio/Capricorn; lá số đêm; đi thuận; nhận trine/sextile từ Jupiter/Venus; không bị Saturn chiếu căng</td><td>Ở Libra/Taurus/Cancer; lá số ngày; retrograde; combust; bị Saturn square/opposition; không có benefic hỗ trợ</td></tr><tr><td>Biểu hiện: dũng cảm, quyết đoán, thành công trong những việc cần ra quân, tranh đấu</td><td>Biểu hiện: nóng giận, liều lĩnh, xung đột, thương tích, kiện tụng</td></tr></tbody></table><p><strong>Ví dụ từ sách [Sách]:</strong> Maria von Trapp có Mars ở sign của chính nó (domicile) trong lá số đêm (in sect). Kết quả theo sách là địa vị cao, bà kết hôn với một sĩ quan quân đội cấp cao. Đây là ví dụ cho nguyên tắc: <strong>malefic ở condition tốt có thể mang lại thành công lớn</strong>.</p><p><strong>Insight về angularity (bài vừa học):</strong></p><ul><li>Mars ở <strong>angular</strong> thì khuếch đại tất cả: condition tốt thì thành lãnh đạo, chiến binh, rất rõ ràng; condition xấu thì xung đột, nóng nảy cũng lộ rõ</li><li>Mars ở <strong>cadent</strong> thì kín đáo hơn: người đó có năng lượng nhưng ít khi bộc lộ</li></ul><hr><h2 id="_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">6. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;6. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><h3 id="checklist-đanh-gia-mars" tabindex="-1">Checklist đánh giá Mars <a class="header-anchor" href="#checklist-đanh-gia-mars" aria-label="Permalink to &quot;Checklist đánh giá Mars&quot;">​</a></h3><ol><li>Lá số ngày hay đêm? (Mars in sect khi là đêm)</li><li>Mars ở sign nào? Có dignity hay debility?</li><li>Mars ở house nào? Angular hay cadent? Có phải house 6 (joy)?</li><li>Retrograde hay thuận? Combust hay không?</li><li>Ai chiếu Mars? Đặc biệt xem Saturn (kìm hãm) và Jupiter (nâng đỡ)</li><li>Mars cai quản house nào (Aries và Scorpio nằm ở house mấy)?</li></ol><h3 id="mars-noi-đuoc-gi-ve-nguoi-đo" tabindex="-1">Mars nói được gì về người đó <a class="header-anchor" href="#mars-noi-đuoc-gi-ve-nguoi-đo" aria-label="Permalink to &quot;Mars nói được gì về người đó&quot;">​</a></h3><ul><li><strong>Động lực, cách hành động, cách xử lý xung đột</strong></li><li><strong>Nơi người đó dễ nóng giận hoặc dễ gặp tranh chấp</strong> (house Mars đứng)</li><li><strong>Nghề dùng lửa, sắt, dao, lực</strong>: quân sự, phẫu thuật, thể thao, thợ cơ khí</li><li><strong>Sốt, viêm, chấn thương</strong> (ở mức xu hướng tượng trưng, không phải chẩn đoán)</li></ul><h3 id="cach-noi-voi-nguoi-đoi-dien-vi-du" tabindex="-1">Cách nói với người đối diện (ví dụ) <a class="header-anchor" href="#cach-noi-voi-nguoi-đoi-dien-vi-du" aria-label="Permalink to &quot;Cách nói với người đối diện (ví dụ)&quot;">​</a></h3><ul><li>Mars tốt: &quot;Bạn có nhiều động lực và dám hành động. Khi cần quyết đoán, bạn thường là người ra tay trước.&quot;</li><li>Mars xấu: &quot;Năng lượng của bạn khá mạnh nhưng dễ bốc đồng. Nên có chỗ xả (thể thao, tập luyện) và cân nhắc trước khi phản ứng khi đang nóng.&quot;</li></ul><h3 id="luu-y-rat-quan-trong" tabindex="-1">Lưu ý rất quan trọng <a class="header-anchor" href="#luu-y-rat-quan-trong" aria-label="Permalink to &quot;Lưu ý rất quan trọng&quot;">​</a></h3><ul><li>Những từ như ngoại tình, phá thai, &quot;hủy hoại phụ nữ&quot;, giết người, tra tấn là <strong>ngôn ngữ lịch sử</strong> của sách. Đừng nói thẳng với khách. Chỉ nói ở mức &quot;dễ xung đột, nóng, cần kiểm soát&quot;</li><li>Không dự đoán bạo lực, tai nạn, thương tích cụ thể</li><li>Mars xấu không có nghĩa người đó &quot;xấu&quot;: hãy hỏi thực tế họ trải qua điều gì</li><li>Luôn kết thúc bằng điều họ có thể làm (đúng tinh thần free will ở note_5)</li></ul><hr><h2 id="_7-loi-thuong-gap" tabindex="-1">7. Lỗi thường gặp <a class="header-anchor" href="#_7-loi-thuong-gap" aria-label="Permalink to &quot;7. Lỗi thường gặp&quot;">​</a></h2><ul><li>Cho rằng Mars lúc nào cũng xấu. Mars tốt cho <strong>dũng khí, thành công, địa vị</strong> (ví dụ Maria von Trapp)</li><li>Dùng Pluto làm ruler của Scorpio. Traditional dùng <strong>Mars</strong></li><li>Quên sect: cùng Mars, lá số ngày và lá số đêm cho kết quả rất khác</li><li>Quên rằng Mars gặp Venus là cặp đối lập: lực chia tách gặp lực kết nối. Aspect giữa hai hành tinh này rất đáng chú ý khi xem chuyện tình cảm</li></ul>',45)])])}const m=t(r,[["render",o]]);export{d as __pageData,m as default};
